<?php defined('ABSPATH')||exit; $terms=get_terms(['taxonomy'=>'bp_pack_category','hide_empty'=>true,'orderby'=>'name','order'=>'ASC']); if(is_wp_error($terms))$terms=[]; $query=new WP_Query([ 'post_type'=>'bp_pack','post_status'=>'publish','posts_per_page'=>-1, 'orderby'=>['menu_order'=>'ASC','date'=>'DESC'],'no_found_rows'=>true ]); if(!$query->have_posts())return; $items=[]; foreach($query->posts as $pack){ $pack_terms=wp_get_post_terms($pack->ID,'bp_pack_category'); if(is_wp_error($pack_terms))$pack_terms=[]; $category_ids=array_map('absint',wp_list_pluck($pack_terms,'term_id')); $pack_items=get_post_meta($pack->ID,'_bp_pack_items',true); $pack_items=is_array($pack_items)?$pack_items:[]; $pack_items=array_values(array_filter($pack_items,static fn($item)=>absint($item['product_id']??0)>0)); $description=get_the_excerpt($pack); if(!$description)$description=wp_strip_all_tags($pack->post_content); $items[]=[ 'id'=>$pack->ID, 'number'=>sprintf('%02d',count($items)+1), 'title'=>get_the_title($pack), 'description'=>$description, 'image_id'=>get_post_thumbnail_id($pack->ID), 'badge'=>$pack_terms?$pack_terms[0]->name:'', 'meta'=>sprintf('%s محصول',number_format_i18n(count($pack_items))), 'url'=>get_permalink($pack), 'pack_items'=>$pack_items, 'color'=>get_post_meta($pack->ID,'_bp_pack_color',true), 'category_ids'=>$category_ids, 'attributes'=>['data-category-ids'=>implode(' ',$category_ids)] ]; }
if(!$items)return; $archive_url=get_post_type_archive_link('bp_pack'); ?> <section class="bp-pack-showcase" aria-labelledby="bp-pack-showcase-title"> <div class="bp-pack-showcase__container"> <div class="bp-pack-showcase__header"> <div class="bp-pack-showcase__intro"> <h2 class="bp-pack-showcase__title" id="bp-pack-showcase-title">پک‌های آماده، شروع راحت‌تر</h2> <p class="bp-pack-showcase__subtitle">کمتر دنبال ابزار بگرد؛ بیشتر خلق کن.</p> <?php if($archive_url): ?> <a class="bp-button bp-button--primary bp-pack-showcase__all" href="<?php echo esc_url($archive_url); ?>"> <img class="bp-button__icon" src="<?php echo esc_url(get_theme_file_uri('assets/icons/arrow-left.svg')); ?>" alt="" aria-hidden="true" width="16" height="16" decoding="async"> <span class="bp-button__label">مشاهده همه پک ها</span> </a> <?php endif; ?> </div> <div class="bp-pack-showcase__filters" role="group" aria-label="فیلتر دسته‌بندی پک‌ها" data-pack-filters> <button class="bp-pack-showcase__filter is-active" type="button" data-pack-filter="all" aria-pressed="true">همه</button> <?php foreach($terms as $term): ?> <button class="bp-pack-showcase__filter" type="button" data-pack-filter="<?php echo esc_attr($term->term_id); ?>" aria-pressed="false"><?php echo esc_html($term->name); ?></button> <?php endforeach; ?> </div> </div> <?php get_template_part('template-parts/components/carousel/carousel',null,[ 'id'=>'bp-pack-carousel', 'class'=>'bp-pack-showcase__carousel', 'label'=>'پک‌های آماده', 'items'=>$items, 'render_item'=>static function($item,$index){ get_template_part('template-parts/components/cards/pack-card',null,[ 'number'=>$item['number'], 'image_id'=>$item['image_id'], 'badge'=>$item['badge'], 'title'=>$item['title'], 'description'=>$item['description'], 'meta'=>$item['meta'], 'button_text'=>'مشاهده پک', 'button_url'=>$item['url'], 'pack_id'=>$item['id'], 'pack_items'=>$item['pack_items'], 'color'=>$item['color'] ]); }
]); ?> </div> </section> <?php wp_reset_postdata(); ?>